#!/usr/bin/env bash
# 031 -- testes da futura V1.0.276 (calendario do Airbnb) numa copia do codigo instalado (1.0.275) em /tmp. Nada instalado.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v276.XXXX)
echo "" | base64 -d > $T/p.patch
echo "19f4066bb37ad7f22fb4841497dc6e0962ceb64c5777201cabe710a7dce5495f  $T/p.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
mkdir -p $T/repo && (cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null) | (cd $T/repo && tar xf - 2>/dev/null)
cd $T/repo && echo "copia: $(grep -oP 'VERSAO = "\K[^"]+' SISTEMA/api/app/versao.py)" && patch -p1 -s --no-backup-if-mismatch < $T/p.patch && echo "pacote 276 aplicado"
cd $T/repo/SISTEMA
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 600 /opt/PMS-Banana-AI/SISTEMA/.venv/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes novos"; P -q api/app/entrada/tests/test_v1276_airbnb_ical.py | grep -vE '^\s*$' | tail -50 | cut -c1-240
echo "== suite inteira"; P -q --maxfail=60 api | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -40 | cut -c1-200
rm -rf $T
